<script setup>
import {ref} from 'vue';import {s,dateText,refreshLatest} from './store';
const open=ref(false);
const time=v=>v?new Date(v).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'—';
</script><template><div class="report-stamp"><div class="toolbar"><div><strong>{{s.event.name}}</strong><span class="muted stamp-time">{{s.filters.snapshot?'Phiên lịch sử':'Dữ liệu mới nhất'}} · {{time(s.report?.generatedAt)}}</span></div><div class="row" data-html2canvas-ignore><MButton variant="link" :aria-expanded="open" aria-controls="report-metadata" @click="open=!open">{{open?'Thu gọn':'Thông tin dữ liệu'}}</MButton><MButton v-if="!s.filters.snapshot" variant="secondary" :loading="s.refreshBusy" @click="refreshLatest">Cập nhật ngay</MButton></div></div>
<div v-if="open" id="report-metadata" class="card stack"><p class="muted">{{!s.filters.from&&!s.filters.to?'Toàn bộ thời gian đã nhập':'Thời gian submit: '+(s.filters.from?dateText(s.filters.from):'Từ đầu')+' → '+(s.filters.to?dateText(s.filters.to):'Mới nhất')}}</p><p class="muted">Nguyên tắc lọc trùng: {{({none:'Không lọc trùng',email:'Email',phone:'Số điện thoại'})[s.event.settings.dedup]}}. Dòng thiếu thông tin dùng để lọc trùng vẫn được giữ.</p><p v-if="s.event.source" class="muted">{{s.event.source.enabled?'Tự cập nhật Google Sheet':'Đồng bộ đang tắt'}} · Kiểm tra nguồn: {{time(s.event.synced_at)}}</p></div>
<p v-if="Object.keys(s.sources).length||s.filters.from||s.filters.to" class="muted">{{s.filters.from?dateText(s.filters.from):'Từ đầu'}} → {{s.filters.to?dateText(s.filters.to):'Mới nhất'}}<span v-for="(v,k) in s.sources" :key="k"> · {{k}}: {{v||'Chưa xác định'}}</span></p>
<p v-if="s.refreshWarning||s.event.sync_error" class="notice" role="status">{{s.refreshWarning||s.event.sync_error}} Đang giữ dữ liệu đã nhập gần nhất.</p><p v-if="s.report?.quality.invalidDates" class="notice">{{s.report.quality.invalidDates}} dòng chưa có ngày hợp lệ: được tính khi xem toàn bộ, không nằm trong bộ lọc ngày.</p>
</div></template>
